:root {
    --bg-gradient-start: #667eea;
    --bg-gradient-end: #764ba2;
    --card-bg: rgba(255, 255, 255, 0.95);
    --card-border: rgba(255, 255, 255, 0.5);
    --text-main: #0f172a;
    --text-muted: #64748b;
    --font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--font-family);
    background: linear-gradient(135deg, var(--bg-gradient-start) 0%, var(--bg-gradient-end) 100%);
    color: var(--text-main);
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
    width: 100vw;
    overflow: hidden;
}

.container {
    width: 100%;
    max-width: 520px;
    padding: 24px;
}

.card {
    background: var(--card-bg);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid var(--card-border);
    border-radius: 32px;
    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25), 0 0 0 1px rgba(255,255,255,0.2) inset;
    padding: 40px;
    display: flex;
    flex-direction: column;
    gap: 32px;
    opacity: 0;
    transform: translateY(20px);
    animation: fadeUp 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.hidden {
    display: none !important;
}

@keyframes fadeUp {
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* State Messages */
.status-message {
    background: var(--card-bg);
    border-radius: 24px;
    padding: 40px;
    text-align: center;
    box-shadow: 0 20px 40px rgba(0,0,0,0.2);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
}

.spinner {
    width: 40px;
    height: 40px;
    border: 4px solid #e2e8f0;
    border-top-color: #3b82f6;
    border-radius: 50%;
    animation: spin 1s linear infinite;
}

.status-message p {
    font-size: 1.125rem;
    color: var(--text-muted);
    font-weight: 500;
}

.status-message svg {
    width: 48px;
    height: 48px;
    color: #ef4444;
}

/* Header */
header {
    text-align: center;
}

.location-name {
    font-size: 2.25rem;
    font-weight: 800;
    letter-spacing: -0.025em;
    margin-bottom: 4px;
    color: var(--text-main);
}

.date-string {
    font-size: 1rem;
    font-weight: 500;
    color: var(--text-muted);
}

/* Main Weather Info */
.main-weather {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 32px;
}

.icon-container {
    width: 100px;
    height: 100px;
    transition: all 0.3s ease;
}

.weather-details {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.condition {
    font-size: 1.75rem;
    font-weight: 700;
    line-height: 1.2;
    color: var(--text-main);
}

.temps {
    display: flex;
    gap: 16px;
    font-size: 1.125rem;
    font-weight: 600;
    color: var(--text-muted);
}

.temps .max {
    color: var(--text-main);
}

/* Hourly Scroll */
.hourly-section {
    background: rgba(248, 250, 252, 0.7);
    border-radius: 24px;
    padding: 24px;
    border: 1px solid rgba(226, 232, 240, 0.8);
}

.hourly-scroll {
    display: flex;
    overflow-x: auto;
    gap: 8px;
    padding-bottom: 8px;
    scrollbar-width: none; /* Firefox */
    -ms-overflow-style: none;  /* IE and Edge */
}

.hourly-scroll::-webkit-scrollbar {
    display: none; /* Chrome, Safari, Opera */
}

.hourly-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    min-width: 64px;
    padding: 12px 8px;
    border-radius: 16px;
    transition: background 0.2s ease;
}

.hourly-item:hover {
    background: rgba(0, 0, 0, 0.04);
}

.hourly-item .time {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--text-muted);
}

.hourly-item .temp {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--text-main);
}

